def get_best_path(s):
    dp = [1]*len(s)
    for i in range(1, len(s)):
        for j in range(i-1, -1, -1):
            if s[i] == s[j]:
                dp[i] = max(dp[i], dp[j] + 1)
    paths = []
    for i in range(len(s)):
        for j in range(i+1, len(s)):
            if dp[i] == dp[j] and dp[j] == dp[j-1] + 1:
                paths.append(s[i:j+1])
    max_length = 0
    best_path = ""
    for path in paths:
        if len(path) > max_length:
            max_length = len(path)
            best_path = path
    return max_length, best_path
```
