import sys

def minimally_unused_wire_length(N, M):
    if N % 2 == 1:
        minimum_wire_length = (N - 1) * ((N + 1) * M // (2 * N)) * (N - 2)
        if minimum_wire_length > M:
            return -1
    else:
        minimum_wire_length = (N - 1) * ((N) * M // (2 * N)) * (N - 2)
        if minimum_wire_length > M:
            return -1
    return M - minimum_wire_length

def main():
    T = int(input())
    for t in range(T):
        N, M = map(int, input().split())
        unused_wire_length = minimally_unused_wire_length(N, M)
        print(unused_wire_length)

if __name__ == "__main__":
    main()
